/* Tech Robòtica · unitat 8 «El meu robot» */
Object.assign(TBADGE, {
  k_dissenya: { id: 'k_dissenya', ico: '📐', n: 'Dissenyador/a de missions|Diseñador/a de misiones', d: "Has dissenyat la teva pròpia pista i una missió amb objectiu, obstacles i comprovacions.|Has diseñado tu propia pista y una misión con objetivo, obstáculos y comprobaciones." },
  k_proves: { id: 'k_proves', ico: '🧪', n: 'Enginyer/a de proves|Ingeniero/a de pruebas', d: "Programes a trams, depures amb llums i números i proves el programa fins que funciona.|Programas por tramos, depuras con luces y números y pruebas el programa hasta que funciona." },
  k_real: { id: 'k_real', ico: '🔌', n: 'Del simulador al robot|Del simulador al robot', d: "Passes el programa a MakeCode, el descarregues al Maqueen i el calibres al món real.|Pasas el programa a MakeCode, lo descargas en el Maqueen y lo calibras en el mundo real." },
  k_enginyer: { id: 'k_enginyer', ico: '🎓', n: 'Enginyer/a de robots|Ingeniero/a de robots', d: "Has presentat el teu robot i la teva missió davant de tothom i has acabat el curs de robòtica.|Has presentado tu robot y tu misión delante de todo el mundo y has terminado el curso de robótica." }
});
ROBOTICA_UNITS[8] = { t: 'El meu robot|Mi robot', d: 'Dissenya, programa i presenta la teva missió|Diseña, programa y presenta tu misión', color: '#E2574C', s: [
  /* ---------- Sessió 1 · Dissenya la missió ---------- */
  { id: 'k8-1', t: 'Dissenya la missió|Diseña la misión', min: 45, badge: 'k_dissenya',
    learn: ["Una bona missió té un objectiu clar, obstacles que fan pensar i una manera de comprovar-la.|Una buena misión tiene un objetivo claro, obstáculos que hacen pensar y una manera de comprobarla.",
      "Les millors missions necessiten un sensor: així el robot decideix sol.|Las mejores misiones necesitan un sensor: así el robot decide solo.",
      "Primer es dibuixa en una quadrícula de paper (1 casella = 10 cm) i després es passa a l'editor.|Primero se dibuja en una cuadrícula de papel (1 casilla = 10 cm) y después se pasa al editor."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Comencem l'última unitat del curs! Quin sensor faries servir perquè el Maqueen s'aturi <b>just abans d'una caixa</b>?|¡Empezamos la última unidad del curso! ¿Qué sensor usarías para que el Maqueen se pare <b>justo antes de una caja</b>?",
        opts: ["Els ultrasons: mesuren la distància en cm|Los ultrasonidos: miden la distancia en cm", 'Els sensors de línia de sota|Los sensores de línea de abajo', 'Els sensors de llum|Los sensores de luz'], a: 0,
        ex: "Els ultrasons envien un so i n'escolten l'eco: així saben a quants centímetres hi ha l'obstacle de davant.|Los ultrasonidos envían un sonido y escuchan su eco: así saben a cuántos centímetros está el obstáculo de delante." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'lab', title: 'La Mostra de Robots|La Muestra de Robots',
        t: "El Museu de Ciències de l'illa prepara la <b>Mostra de Robots</b>, i t'ha convidat com a enginyer/a! Cada participant hi porta una missió <b>inventada per ell o ella</b>: la pista, el repte i el programa. En aquesta unitat la dissenyaràs, la programaràs, la passaràs al Maqueen de veritat i la presentaràs al públic.|El Museo de Ciencias de la isla prepara la <b>Muestra de Robots</b>, ¡y te ha invitado como ingeniero/a! Cada participante lleva una misión <b>inventada por él o ella</b>: la pista, el reto y el programa. En esta unidad la diseñarás, la programarás, la pasarás al Maqueen de verdad y la presentarás al público." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'happy',
        t: "BIP! Fins ara les missions te les preparàvem nosaltres. Avui canviem els papers: <b>tu decideixes</b> on són les caixes, la cinta i la meta, i què ha d'aconseguir el robot. Però compte: una missió s'ha de poder fer!|¡BIP! Hasta ahora las misiones te las preparábamos nosotros. Hoy cambiamos los papeles: <b>tú decides</b> dónde están las cajas, la cinta y la meta, y qué tiene que conseguir el robot. Pero cuidado: ¡una misión se tiene que poder hacer!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Una bona missió|Una buena misión', t: 'Què té una missió ben pensada?|¿Qué tiene una misión bien pensada?', anim: 'k8good',
          x: "Una missió de robot té quatre parts: un <b>objectiu clar</b> (arribar a la meta, portar una llauna, seguir la cinta), <b>obstacles</b> que obliguen a pensar (caixes, revolts), un <b>sensor</b> que el robot necessita fer servir i una manera de <b>comprovar</b> si s'ha complert.|Una misión de robot tiene cuatro partes: un <b>objetivo claro</b> (llegar a la meta, llevar una lata, seguir la cinta), <b>obstáculos</b> que obligan a pensar (cajas, curvas), un <b>sensor</b> que el robot necesita usar y una manera de <b>comprobar</b> si se ha cumplido.",
          tip: "Pensa en el públic de la Mostra: una missió clara s'entén d'un cop d'ull.|Piensa en el público de la Muestra: una misión clara se entiende de un vistazo." },
        { k: 'Comprovar|Comprobar', t: 'Com sabem que la missió està complerta?|¿Cómo sabemos que la misión está cumplida?',
          robo: { w: { w: 120, h: 80, bot: [15, 45, 90], walls: [[50.5, .5, 9, 9], [50.5, 10.5, 9, 9], [50.5, 60.5, 9, 9], [50.5, 70.5, 9, 9]], objs: [{ x: 45, y: 45, r: 3, kind: 'can' }], zones: [{ id: 'meta', r: [90, 30, 20, 20], col: 'green', label: 'META|META' }] }, prog: 'start{ run:all,fwd,150 wait:5000 stop:all }' },
          x: "A l'editor triaràs les <span class='hl'>comprovacions</span> de la teva missió: arribar a la meta i aturar-s'hi, no xocar, portar la llauna a la meta, fer-ho en menys de 20 segons o seguir la cinta fins al final. L'app les revisarà cada vegada que s'executi el programa, com un jutge que no es distreu mai.|En el editor elegirás las <span class='hl'>comprobaciones</span> de tu misión: llegar a la meta y pararse, no chocar, llevar la lata a la meta, hacerlo en menos de 20 segundos o seguir la cinta hasta el final. La app las revisará cada vez que se ejecute el programa, como un juez que no se distrae nunca.",
          tip: "Aquí la missió és «portar la llauna a la meta» i «sense xocar».|Aquí la misión es «llevar la lata a la meta» y «sin chocar»." },
        { k: 'Un sensor|Un sensor', t: 'Missions que necessiten sentir|Misiones que necesitan sentir',
          robo: { w: { w: 120, h: 60, bot: [15, 30, 90], walls: [[80.5, 10.5, 9, 39]] }, prog: 'forever{ if:dist<10{ stop:all car:all,red } else{ run:all,fwd,150 car:all,green } }' },
          x: "Si la missió es pot resoldre només amb temps («endavant 3 segons»), el robot va a cegues. Si la caixa pot estar més a prop o més lluny, o si hi ha una cinta per seguir, el robot <b>ha de sentir</b>: aquest para sol a 10 cm de la vitrina, sigui on sigui.|Si la misión se puede resolver solo con tiempo («adelante 3 segundos»), el robot va a ciegas. Si la caja puede estar más cerca o más lejos, o si hay una cinta que seguir, el robot <b>tiene que sentir</b>: este para solo a 10 cm de la vitrina, esté donde esté.",
          tip: "Les missions amb sensors també funcionen millor al robot de veritat.|Las misiones con sensores también funcionan mejor en el robot de verdad." },
        { k: 'Compte!|¡Cuidado!', t: 'Ni massa fàcil ni impossible|Ni demasiado fácil ni imposible',
          robo: { w: { w: 120, h: 60, bot: [15, 30, 90], zones: [{ id: 'meta', r: [24, 20, 20, 20], col: 'green', label: 'META|META' }] }, prog: 'start{ run:all,fwd,150 wait:700 stop:all }' },
          x: "Aquesta meta és tan a prop que la missió s'acaba en un segon: avorreix. I una meta envoltada de caixes per tots costats seria impossible. La bona missió és <span class='hl'>al punt</span>: fa pensar una mica, però té solució.|Esta meta está tan cerca que la misión se termina en un segundo: aburre. Y una meta rodeada de cajas por todos lados sería imposible. La buena misión está <span class='hl'>en su punto</span>: hace pensar un poco, pero tiene solución.",
          bad: 'Com més caixes i parets, millor és la missió.|Cuantas más cajas y paredes, mejor es la misión.', good: 'Una bona missió fa pensar, però sempre té solució.|Una buena misión hace pensar, pero siempre tiene solución.' },
        { k: 'Primer, en paper|Primero, en papel', t: "L'esbós a escala|El boceto a escala", anim: 'k8sketch',
          x: "Els enginyers i enginyeres dibuixen un <span class='hl'>esbós</span> abans de construir. La teva pista fa 120 × 80 cm, com un tapet de l'aula: en una quadrícula de 12 × 8 caselles, <b>cada casella són 10 cm</b>. Dibuixa-hi les caixes, la cinta, la meta i el robot, i després passa-ho a l'editor casella per casella.|Los ingenieros e ingenieras dibujan un <span class='hl'>boceto</span> antes de construir. Tu pista mide 120 × 80 cm, como un tapete del aula: en una cuadrícula de 12 × 8 casillas, <b>cada casilla son 10 cm</b>. Dibuja las cajas, la cinta, la meta y el robot, y después pásalo al editor casilla por casilla.",
          tip: "Com que és a escala, després la podràs construir a terra amb cinta i caixes de veritat.|Como está a escala, después la podrás construir en el suelo con cinta y cajas de verdad." }
      ] },
      { k: 'quiz', ph: 'mans', q: "Tres enginyers/es han dissenyat una missió per a la Mostra. <b>Quina està més ben pensada?</b>|Tres ingenieros/as han diseñado una misión para la Muestra. <b>¿Cuál está mejor pensada?</b>",
        opts: ["La meta és a 10 cm del robot, sense res pel mig|La meta está a 10 cm del robot, sin nada en medio", "Una cinta amb revolts fins a una caixa: el robot l'ha de seguir i aturar-se davant la caixa|Una cinta con curvas hasta una caja: el robot tiene que seguirla y pararse delante de la caja", "La meta és dins d'un quadrat de caixes tancat|La meta está dentro de un cuadrado de cajas cerrado"], a: 1,
        ex: "La primera és massa fàcil i la tercera, impossible. La segona té objectiu, obstacles, dos sensors (línia i ultrasons) i es pot comprovar.|La primera es demasiado fácil y la tercera, imposible. La segunda tiene objetivo, obstáculos, dos sensores (línea y ultrasonidos) y se puede comprobar." },
      { k: 'seq', ph: 'mans', q: "Com es dissenya una missió? <b>Ordena els passos</b> com ho faria un enginyer/a.|¿Cómo se diseña una misión? <b>Ordena los pasos</b> como lo haría un ingeniero/a.",
        items: ["Penso la idea: què ha d'aconseguir el robot i quin sensor farà servir?|Pienso la idea: ¿qué tiene que conseguir el robot y qué sensor usará?", "Dibuixo la pista a la quadrícula de paper|Dibujo la pista en la cuadrícula de papel", "La passo a l'editor, trio les comprovacions i li poso un nom|La paso al editor, elijo las comprobaciones y le pongo un nombre", "Comprovo que es pot fer i, si cal, la millora|Compruebo que se puede hacer y, si hace falta, la mejoro"],
        ex: "Pensar, dibuixar, construir i comprovar: és el camí de qualsevol projecte d'enginyeria.|Pensar, dibujar, construir y comprobar: es el camino de cualquier proyecto de ingeniería." },
      { k: 'unplug', ph: 'mans', ico: '📐', title: 'La pista del menjador|La pista del comedor', t: "Amb algú de casa, dissenyeu una missió de robot en un espai lliure de terra.|Con alguien de casa, diseñad una misión de robot en un espacio libre del suelo.",
        steps: ["Marqueu la sortida i la meta amb dos objectes (un mitjó, un tap…).|Marcad la salida y la meta con dos objetos (un calcetín, un tapón…).",
          "Poseu-hi un obstacle (un llibre o una caixa) i un camí de cordill o de llana.|Poned un obstáculo (un libro o una caja) y un camino de cordel o de lana.",
          "Una persona fa de robot amb els ulls tancats; l'altra li diu només el que «senten» els sensors: «línia a l'esquerra», «caixa a prop»…|Una persona hace de robot con los ojos cerrados; la otra le dice solo lo que «sienten» los sensores: «línea a la izquierda», «caja cerca»…",
          "Era massa fàcil o massa difícil? Canvieu un obstacle de lloc i torneu-ho a provar.|¿Era demasiado fácil o demasiado difícil? Cambiad un obstáculo de sitio y volved a probar."],
        tip: "Mesureu la pista a pams: així practiqueu el dibuix a escala.|Medid la pista a palmos: así practicáis el dibujo a escala." },
      { k: 'quiz', ph: 'prova', q: "La missió de la Rita és «Rescata la llauna»: el robot ha d'empènyer una llauna fins a la meta sense tocar les caixes. <b>Quines comprovacions ha de triar a l'editor?</b>|La misión de Rita es «Rescata la lata»: el robot tiene que empujar una lata hasta la meta sin tocar las cajas. <b>¿Qué comprobaciones tiene que elegir en el editor?</b>",
        opts: ["«Portar la llauna a la meta» i «Sense xocar»|«Llevar la lata a la meta» y «Sin chocar»", "Només «En menys de 20 segons»|Solo «En menos de 20 segundos»", "«Seguir la cinta fins al final»|«Seguir la cinta hasta el final»"], a: 0,
        ex: "Les comprovacions han de dir exactament el que demana la missió: la llauna a la meta i cap xoc.|Las comprobaciones tienen que decir exactamente lo que pide la misión: la lata en la meta y ningún choque." },
      { k: 'rpredict', ph: 'prova', q: "Una pista dibuixada a l'editor: cada casella fa 10 cm. El robot avança, gira sobre si mateix i torna a avançar. <b>On acabarà?</b>|Una pista dibujada en el editor: cada casilla mide 10 cm. El robot avanza, gira sobre sí mismo y vuelve a avanzar. <b>¿Dónde terminará?</b>",
        w: { w: 120, h: 80, bot: [15, 25, 90], walls: [[90.5, .5, 9, 9], [100.5, .5, 9, 9]], marks: { A: [76, 25], B: [46, 56], C: [76, 56] } }, scripts: ['start'],
        prog: 'start{ run:all,fwd,150 wait:2000 stop:all run:L,fwd,100 run:R,back,100 wait:590 stop:all run:all,fwd,150 wait:2000 stop:all }', a: 'B',
        ex: "Primer avança uns 30 cm (tres caselles). Després, el motor esquerre endavant i el dret enrere el fan girar 90° cap a la dreta: ara mira avall i avança tres caselles més.|Primero avanza unos 30 cm (tres casillas). Después, el motor izquierdo adelante y el derecho atrás lo hacen girar 90° hacia la derecha: ahora mira hacia abajo y avanza tres casillas más." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de Maqueen dissenyador! Dibuixa a l'aire, amb tot el braç, una pista amb <b>dos revolts</b>. Ara recorre-la caminant al teu lloc: endavant, gira, endavant… i quan arribis a la meta, encén els «llums» obrint les mans ben fort!|¡Haz de Maqueen diseñador! Dibuja en el aire, con todo el brazo, una pista con <b>dos curvas</b>. Ahora recórrela caminando en tu sitio: adelante, gira, adelante… ¡y cuando llegues a la meta, enciende las «luces» abriendo las manos bien fuerte!" },
      { k: 'story', ph: 'repte', who: 'numi', t: "Abans de dissenyar la teva, <b>escalfem motors</b> amb quatre missions de prova fetes amb l'editor, una per cada gran eina del curs: motors i temps, ultrasons, línia i empènyer objectes.|Antes de diseñar la tuya, <b>calentamos motores</b> con cuatro misiones de prueba hechas con el editor, una por cada gran herramienta del curso: motores y tiempo, ultrasonidos, línea y empujar objetos." },
      { k: 'robo', ph: 'repte', q: "<b>Motors i temps.</b> Porta el robot fins a la <b>META</b> sense tocar cap caixa: endavant, gir de 90° a l'esquerra i endavant. Recorda: cada casella fa 10 cm.|<b>Motores y tiempo.</b> Lleva el robot hasta la <b>META</b> sin tocar ninguna caja: adelante, giro de 90° a la izquierda y adelante. Recuerda: cada casilla mide 10 cm.",
        w: { w: 120, h: 80, bot: [15, 65, 90], walls: [[20.5, .5, 9, 9], [20.5, 10.5, 9, 9], [20.5, 20.5, 9, 9], [20.5, 30.5, 9, 9], [90.5, 40.5, 9, 9], [90.5, 50.5, 9, 9], [100.5, 50.5, 9, 9]], zones: [{ id: 'meta', r: [50, 0, 20, 20], col: 'green', label: 'META|META' }], goal: [{ k: 'zone', id: 'meta', stop: true }, { k: 'nohit' }], time: 20 },
        pal: ['run', 'stop', 'wait'], ops: [], scripts: ['start'],
        sol: 'start{ run:all,fwd,150 wait:2800 stop:all run:L,back,100 run:R,fwd,100 wait:590 stop:all run:all,fwd,150 wait:3300 stop:all }',
        hint: "Fins a sota la meta hi ha uns 45 cm: a 150, uns 3 segons. Per girar a l'esquerra, motor esquerre enrere i dret endavant a 100 durant uns 590 ms.|Hasta debajo de la meta hay unos 45 cm: a 150, unos 3 segundos. Para girar a la izquierda, motor izquierdo atrás y derecho adelante a 100 durante unos 590 ms." },
      { k: 'robo', ph: 'repte', q: "<b>Ultrasons.</b> El robot s'ha d'aturar a entre 4 i 12 cm de la vitrina, sense tocar-la. Però a cada pista la vitrina és en un lloc diferent: el mateix programa ha de funcionar a les <b>3 pistes</b>.|<b>Ultrasonidos.</b> El robot tiene que pararse a entre 4 y 12 cm de la vitrina, sin tocarla. Pero en cada pista la vitrina está en un sitio diferente: el mismo programa tiene que funcionar en las <b>3 pistas</b>.",
        w: { w: 120, h: 80, bot: [15, 45, 90], walls: [[90.5, 20.5, 9, 9], [90.5, 30.5, 9, 9], [90.5, 40.5, 9, 9], [90.5, 50.5, 9, 9], [90.5, 60.5, 9, 9]], goal: [{ k: 'near', min: 4, max: 12 }, { k: 'nohit' }], time: 15,
          alts: [{ walls: [[60.5, 20.5, 9, 9], [60.5, 30.5, 9, 9], [60.5, 40.5, 9, 9], [60.5, 50.5, 9, 9], [60.5, 60.5, 9, 9]] }, { walls: [[110.5, 10.5, 9, 9], [110.5, 20.5, 9, 9], [110.5, 30.5, 9, 9], [110.5, 40.5, 9, 9], [110.5, 50.5, 9, 9], [110.5, 60.5, 9, 9]] }] },
        pal: ['run', 'stop', 'if', 'else'], ops: ['dist'], scripts: ['forever'],
        sol: 'forever{ if:dist<10{ stop:all } else{ run:all,fwd,150 } }',
        hint: "Dins de «per sempre», pregunta-ho a cada moment: si la distància és més petita que 10, atura't; si no, endavant.|Dentro de «para siempre», pregúntalo en cada momento: si la distancia es más pequeña que 10, párate; si no, adelante." },
      { k: 'robo', ph: 'repte', q: "<b>Línia.</b> Segueix la cinta negra amb els sensors L i R i passa pels dos punts del circuit. Si el sensor esquerre veu negre, gira a l'esquerra; si el veu el dret, a la dreta.|<b>Línea.</b> Sigue la cinta negra con los sensores L y R y pasa por los dos puntos del circuito. Si el sensor izquierdo ve negro, gira a la izquierda; si lo ve el derecho, a la derecha.",
        w: { w: 120, h: 80, bot: [15, 65, 90], lines: [{ p: [[15, 65], [45, 65], [55, 55], [55, 35], [65, 25], [115, 25]] }], goal: [{ k: 'cps', pts: [[55, 45], [100, 25]], r: 7 }], time: 25 },
        pal: ['run', 'stop', 'patrol', 'if', 'else', 'and'], ops: ['L', 'M', 'R'], scripts: ['start', 'forever'],
        sol: 'forever{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } }',
        hint: "Per girar a l'esquerra, la roda esquerra va a poc a poc (40) i la dreta, de pressa (140). Si cap sensor no veu la cinta, endavant.|Para girar a la izquierda, la rueda izquierda va despacio (40) y la derecha, deprisa (140). Si ningún sensor ve la cinta, adelante." },
      { k: 'robo', ph: 'repte', q: "<b>Empènyer.</b> Rescata la llauna: empeny-la fins a la <b>META</b> sense tocar les caixes del pas estret.|<b>Empujar.</b> Rescata la lata: empújala hasta la <b>META</b> sin tocar las cajas del paso estrecho.",
        w: { w: 120, h: 80, bot: [15, 45, 90], walls: [[50.5, .5, 9, 9], [50.5, 10.5, 9, 9], [50.5, 20.5, 9, 9], [50.5, 50.5, 9, 9], [50.5, 60.5, 9, 9], [50.5, 70.5, 9, 9]], objs: [{ x: 45, y: 45, r: 3, kind: 'can' }], zones: [{ id: 'meta', r: [90, 30, 20, 20], col: 'green', label: 'META|META' }], goal: [{ k: 'push', obj: 0, id: 'meta' }, { k: 'nohit' }], time: 20 },
        pal: ['run', 'stop', 'wait'], ops: [], scripts: ['start'],
        sol: 'start{ run:all,fwd,150 wait:5000 stop:all }',
        hint: "La llauna va al davant del robot: quan el robot avança, ella també. Calcula quant ha d'avançar perquè la llauna entri a la meta.|La lata va delante del robot: cuando el robot avanza, ella también. Calcula cuánto tiene que avanzar para que la lata entre en la meta." },
      { k: 'rdesign', ph: 'crea', q: "<b>Ara, la teva missió!</b> Passa a l'editor el dibuix que has fet en paper (o inventa'n una de nova): tria una eina i toca les caselles. Posa-hi la meta, el robot, obstacles i, si vols, cinta i llaunes. Tria les comprovacions, dona-li un nom i desa-la.|<b>¡Ahora, tu misión!</b> Pasa al editor el dibujo que has hecho en papel (o inventa una nueva): elige una herramienta y toca las casillas. Pon la meta, el robot, obstáculos y, si quieres, cinta y latas. Elige las comprobaciones, dale un nombre y guárdala.",
        crit: ['Té un objectiu clar i la meta és ben visible|Tiene un objetivo claro y la meta se ve bien', 'Té obstacles que fan pensar|Tiene obstáculos que hacen pensar', 'El robot necessitarà almenys un sensor|El robot necesitará al menos un sensor', 'Té solució: no és massa fàcil ni impossible|Tiene solución: no es demasiado fácil ni imposible'],
        w: { w: 120, h: 80 }, slot: 'k8' },
      { k: 'quiz', ph: 'tanca', q: "Per què és bona idea dibuixar la pista en una quadrícula on cada casella fa 10 cm?|¿Por qué es buena idea dibujar la pista en una cuadrícula donde cada casilla mide 10 cm?",
        opts: ["Perquè està a escala: després es pot construir a terra amb les mides de veritat|Porque está a escala: después se puede construir en el suelo con las medidas de verdad", "Perquè així el robot va més de pressa|Porque así el robot va más deprisa", "Perquè el paper és més bonic que la pantalla|Porque el papel es más bonito que la pantalla"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Una missió que es pot fer amb «endavant 2 segons i atura» i prou…|Una misión que se puede hacer con «adelante 2 segundos y para» y ya está…",
        opts: ["Segurament és massa fàcil: li falta un obstacle o un sensor|Seguramente es demasiado fácil: le falta un obstáculo o un sensor", "És la millor missió possible|Es la mejor misión posible", "És impossible|Es imposible"], a: 0,
        ex: "Una bona missió fa pensar: un revolt, una caixa que cal esquivar o una cinta que cal seguir.|Una buena misión hace pensar: una curva, una caja que hay que esquivar o una cinta que hay que seguir." },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 2 · Programa i prova ---------- */
  { id: 'k8-2', t: 'Programa i prova|Programa y prueba', min: 45, badge: 'k_proves',
    learn: ["Els equips d'enginyeria treballen en cicle: planifiquen, programen, proven i milloren.|Los equipos de ingeniería trabajan en ciclo: planifican, programan, prueban y mejoran.",
      "Una missió llarga es programa a trams, i els llums i la pantalla ajuden a trobar els errors.|Una misión larga se programa por tramos, y las luces y la pantalla ayudan a encontrar los errores.",
      "Un programa és bo quan funciona en pistes diferents, no només una vegada.|Un programa es bueno cuando funciona en pistas diferentes, no solo una vez."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "La setmana passada vas dissenyar la teva missió. Què ha de tenir una bona missió?|La semana pasada diseñaste tu misión. ¿Qué tiene que tener una buena misión?",
        opts: ["Un objectiu clar, obstacles, un sensor i comprovacions|Un objetivo claro, obstáculos, un sensor y comprobaciones", "Tantes caixes com sigui possible|Tantas cajas como sea posible", "Només una meta al costat del robot|Solo una meta al lado del robot"], a: 0 },
      { k: 'story', ph: 'missio', who: 'both', scene: 'lab', title: 'El banc de proves|El banco de pruebas',
        t: "Al laboratori del museu hi ha el <b>banc de proves</b>: la taula on l'equip d'enginyeria prova cada robot una vegada i una altra abans de la Mostra. Avui programaràs la teva missió, la provaràs, trobaràs els errors i la faràs encara millor.|En el laboratorio del museo está el <b>banco de pruebas</b>: la mesa donde el equipo de ingeniería prueba cada robot una y otra vez antes de la Muestra. Hoy programarás tu misión, la probarás, encontrarás los errores y la harás todavía mejor." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'El cicle|El ciclo', t: "Planifica, programa, prova, millora|Planifica, programa, prueba, mejora", anim: 'k8cycle',
          x: "Cap enginyer/a no l'encerta a la primera. Treballen en un <span class='hl'>cicle</span>: <b>planifiquen</b> què ha de fer el robot, ho <b>programen</b>, ho <b>proven</b> i ho <b>milloren</b>… i tornen a començar. Cada volta és una versió nova: v1, v2, v3…|Ningún ingeniero/a lo acierta a la primera. Trabajan en un <span class='hl'>ciclo</span>: <b>planifican</b> qué tiene que hacer el robot, lo <b>programan</b>, lo <b>prueban</b> y lo <b>mejoran</b>… y vuelven a empezar. Cada vuelta es una versión nueva: v1, v2, v3…",
          tip: "Si el robot falla, no has fallat tu: has trobat la pista de la versió següent.|Si el robot falla, no has fallado tú: has encontrado la pista de la versión siguiente." },
        { k: 'A trams|Por tramos', t: 'Una missió llarga, a trossos|Una misión larga, a trozos',
          robo: { w: { w: 120, h: 80, bot: [15, 65, 90], lines: [{ p: [[15, 65], [45, 65], [55, 55], [55, 35], [65, 25], [115, 25]] }], walls: [[90.5, 20.5, 9, 9]] }, prog: 'forever{ if:dist<10{ stop:all } else{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } } }' },
          x: "Abans de programar, divideix la missió en <span class='hl'>trams</span> i prova'ls d'un en un. Aquí hi ha dos trams: <b>1)</b> seguir la cinta i <b>2)</b> parar davant la caixa. Primer fes que segueixi la cinta; quan funcioni, afegeix-hi el «si distància &lt; 10, atura't».|Antes de programar, divide la misión en <span class='hl'>tramos</span> y pruébalos de uno en uno. Aquí hay dos tramos: <b>1)</b> seguir la cinta y <b>2)</b> parar delante de la caja. Primero haz que siga la cinta; cuando funcione, añade el «si distancia &lt; 10, párate».",
          tip: "Escriu els trams en un paper abans de tocar cap bloc: és el teu pla.|Escribe los tramos en un papel antes de tocar ningún bloque: es tu plan." },
        { k: 'Depurar|Depurar', t: 'Llums i números que expliquen|Luces y números que explican', anim: 'k8debug',
          x: "Quan el robot fa una cosa estranya, fes que t'expliqui què pensa. Posa <b>llums del cotxe</b> de colors a cada branca del «si» (verd: endavant; vermell: atura't) o <b>mostra el número</b> de la distància a la pantalla. Així veus si el problema és el sensor, la condició o els motors.|Cuando el robot hace algo raro, haz que te explique qué piensa. Pon <b>luces del coche</b> de colores en cada rama del «si» (verde: adelante; rojo: párate) o <b>muestra el número</b> de la distancia en la pantalla. Así ves si el problema es el sensor, la condición o los motores.",
          tip: "Depurar vol dir buscar i treure els errors d'un programa: per això aquests llums de prova es diuen «llums de depuració».|Depurar quiere decir buscar y quitar los errores de un programa: por eso estas luces de prueba se llaman «luces de depuración»." },
        { k: 'Cantonades|Esquinas', t: 'Cinta amb cantonades de 90°|Cinta con esquinas de 90°',
          robo: { w: { w: 120, h: 80, bot: [15, 65, 90], lines: [{ p: [[15, 65], [55, 65], [55, 25], [105, 25], [105, 65]] }] }, prog: 'forever{ if:L=1&&R=0{ run:L,back,100 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,back,100 } else{ run:all,fwd,120 } } }' },
          x: "A l'editor, la cinta va de casella en casella i fa <b>cantonades de 90°</b>. Girant en arc (una roda lenta i l'altra ràpida), el robot se'n surt. La solució: a les cantonades, que giri <b>sobre si mateix</b>, amb la roda de dins <b>enrere</b>.|En el editor, la cinta va de casilla en casilla y hace <b>esquinas de 90°</b>. Girando en arco (una rueda lenta y la otra rápida), el robot se sale. La solución: en las esquinas, que gire <b>sobre sí mismo</b>, con la rueda de dentro <b>hacia atrás</b>." },
        { k: 'Compte!|¡Cuidado!', t: 'Una prova no és prou|Una prueba no es suficiente',
          robo: { w: { w: 120, h: 60, bot: [15, 30, 90], walls: [[60.5, 10.5, 9, 39]], time: 6 }, prog: 'start{ run:all,fwd,150 wait:4000 stop:all }' },
          x: "Aquest programa funcionava quan la caixa era més lluny… però algú l'ha moguda i ara hi xoca. Un programa amb temps fixos només funciona en <b>una</b> pista. Prova el teu en situacions diferents: caixes més a prop, més lluny, la sortida una mica girada…|Este programa funcionaba cuando la caja estaba más lejos… pero alguien la ha movido y ahora choca. Un programa con tiempos fijos solo funciona en <b>una</b> pista. Prueba el tuyo en situaciones diferentes: cajas más cerca, más lejos, la salida un poco girada…",
          bad: 'Si ha funcionat una vegada, el programa ja està acabat.|Si ha funcionado una vez, el programa ya está terminado.', good: 'Un bon programa funciona en pistes diferents.|Un buen programa funciona en pistas diferentes.' }
      ] },
      { k: 'rdesign', ph: 'mans', q: "Obre la teva missió i mira-la amb ulls d'enginyer/a abans de programar-la: és tal com la vols? (Si encara no en tens cap, dissenya-la ara.) Quan estigui a punt, desa-la.|Abre tu misión y mírala con ojos de ingeniero/a antes de programarla: ¿es tal como la quieres? (Si aún no tienes ninguna, diséñala ahora.) Cuando esté lista, guárdala.",
        crit: ['Té un objectiu clar i obstacles|Tiene un objetivo claro y obstáculos', "Les comprovacions diuen el que demana la missió|Las comprobaciones dicen lo que pide la misión"],
        w: { w: 120, h: 80 }, slot: 'k8' },
      { k: 'rmybuild', ph: 'mans', q: "Programa la teva missió <b>«{nom}»</b>: és la <b>versió 1</b>. Divideix-la en trams i prova'ls d'un en un. Quan el robot la compleixi, desa-la.|Programa tu misión <b>«{nom}»</b>: es la <b>versión 1</b>. Divídela en tramos y pruébalos de uno en uno. Cuando el robot la cumpla, guárdala.",
        crit: ['El robot compleix totes les comprovacions de la missió|El robot cumple todas las comprobaciones de la misión', 'Has provat el programa tram a tram|Has probado el programa tramo a tramo'],
        pal: ['run', 'stop', 'patrol', 'wait', 'car', 'under', 'note', 'icon', 'num', 'clear', 'set', 'change', 'calc', 'rep', 'while', 'until', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R', 'aL', 'aM', 'aR', 'lL', 'lR', 'A', 'B'], scripts: ['start', 'forever', 'A', 'B'], vars: ['v', 'n'], varNames: { v: 'velocitat|velocidad', n: 'comptador|contador' },
        hint: "Mira on falla el robot: el problema sol ser el tram just abans. Posa-hi llums de colors per saber què «pensa».|Mira dónde falla el robot: el problema suele estar en el tramo justo antes. Pon luces de colores para saber qué «piensa».", slot: 'k8' },
      { k: 'quiz', ph: 'prova', q: "Executes la teva missió i el robot xoca amb una caixa. Què fas primer?|Ejecutas tu misión y el robot choca con una caja. ¿Qué haces primero?",
        opts: ["Miro on i quan xoca, poso llums de depuració i canvio una sola cosa|Miro dónde y cuándo choca, pongo luces de depuración y cambio una sola cosa", "Ho esborro tot i començo de zero|Lo borro todo y empiezo de cero", "Trec la caixa de la pista|Quito la caja de la pista"], a: 0,
        ex: "Si canvies una sola cosa cada vegada, sabràs quina ha arreglat el problema. Treure la caixa faria la missió massa fàcil!|Si cambias una sola cosa cada vez, sabrás cuál ha arreglado el problema. ¡Quitar la caja haría la misión demasiado fácil!" },
      { k: 'quiz', ph: 'prova', q: "Vols saber <b>quina distància</b> mesuren els ultrasons mentre el robot avança. Quin bloc t'ajuda?|Quieres saber <b>qué distancia</b> miden los ultrasonidos mientras el robot avanza. ¿Qué bloque te ayuda?",
        opts: ["«Mostra el número distància» dins de «per sempre»|«Muestra el número distancia» dentro de «para siempre»", "«Espera 1000 ms»|«Espera 1000 ms»", "«Esborra la pantalla»|«Borra la pantalla»"], a: 0,
        ex: "La micro:bit mostra el número de centímetres: així veus què mesura el sensor de veritat.|La micro:bit muestra el número de centímetros: así ves qué mide el sensor de verdad." },
      { k: 'rspot', ph: 'investiga', q: "Aquest robot hauria de parar davant la caixa. Els llums es tornen <b>vermells</b> just a temps… però el robot gira i acaba xocant amb la paret. Executa'l i <b>toca el bloc equivocat</b>.|Este robot debería pararse delante de la caja. Las luces se vuelven <b>rojas</b> justo a tiempo… pero el robot gira y acaba chocando con la pared. Ejecútalo y <b>toca el bloque equivocado</b>.",
        w: { w: 120, h: 60, bot: [15, 30, 90], walls: [[80.5, 10.5, 9, 39]], time: 8 }, scripts: ['forever'],
        prog: 'forever{ if:dist<10{ car:all,red stop:L! } else{ car:all,green run:all,fwd,150 } }',
        yes: "Exacte! Els llums vermells diuen que la condició funciona; el bug és que només s'atura el motor esquerre.|¡Exacto! Las luces rojas dicen que la condición funciona; el bug es que solo se para el motor izquierdo.",
        ex: "Els llums vermells s'encenen: la condició va bé. El bloc equivocat és «atura el motor esquerre»: el dret continua girant. Ha de ser «atura els dos».|Las luces rojas se encienden: la condición va bien. El bloque equivocado es «para el motor izquierdo»: el derecho sigue girando. Tiene que ser «para los dos»." },
      { k: 'robo', ph: 'investiga', q: "Aquesta cinta té <b>cantonades de 90°</b>, com les de l'editor, i el robot se'n surt al primer revolt. <b>Arregla el programa</b>: a les cantonades, la roda de dins ha d'anar <b>enrere</b> perquè giri sobre si mateix.|Esta cinta tiene <b>esquinas de 90°</b>, como las del editor, y el robot se sale en la primera curva. <b>Arregla el programa</b>: en las esquinas, la rueda de dentro tiene que ir <b>hacia atrás</b> para que gire sobre sí mismo.",
        w: { w: 120, h: 80, bot: [15, 65, 90], lines: [{ p: [[15, 65], [55, 65], [55, 25], [105, 25], [105, 65]] }], goal: [{ k: 'cps', pts: [[55, 45], [105, 25], [105, 60]], r: 7 }], time: 35 },
        pal: ['run', 'stop', 'if', 'else', 'and'], ops: ['L', 'R'], scripts: ['forever'],
        prog: 'forever{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } }',
        sol: 'forever{ if:L=1&&R=0{ run:L,back,100 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,back,100 } else{ run:all,fwd,120 } } }',
        hint: "Canvia els dos blocs de la roda lenta: en lloc de «endavant a 40», que vagin «enrere a 100».|Cambia los dos bloques de la rueda lenta: en lugar de «adelante a 40», que vayan «atrás a 100»." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes el cicle de l'enginyer/a amb el cos: <b>planifica</b> (toca't el cap pensant), <b>programa</b> (teclejar a l'aire), <b>prova</b> (tres passos endavant) i <b>millora</b> (estira't ben amunt). I tres voltes més, cada vegada més de pressa!|Haz el ciclo del ingeniero/a con el cuerpo: <b>planifica</b> (tócate la cabeza pensando), <b>programa</b> (teclear en el aire), <b>prueba</b> (tres pasos adelante) y <b>mejora</b> (estírate bien arriba). ¡Y tres vueltas más, cada vez más deprisa!" },
      { k: 'robo', ph: 'repte', q: "<b>Llums de depuració.</b> El robot avança amb els llums del cotxe <b>verds</b> i, quan és a menys de 10 cm de la caixa, s'atura i els posa <b>vermells</b>. Ha de funcionar a les <b>3 pistes</b>.|<b>Luces de depuración.</b> El robot avanza con las luces del coche <b>verdes</b> y, cuando está a menos de 10 cm de la caja, se para y las pone <b>rojas</b>. Tiene que funcionar en las <b>3 pistas</b>.",
        w: { w: 120, h: 60, bot: [15, 30, 90], walls: [[90.5, 10.5, 9, 39]], goal: [{ k: 'at', t: 1, car: 'green', moving: true, why: "Al segon 1, el robot ha d'anar endavant amb els llums verds.|En el segundo 1, el robot tiene que ir adelante con las luces verdes." }, { k: 'near', min: 4, max: 12 }, { k: 'car', c: 'red' }, { k: 'nohit' }], time: 9,
          alts: [{ walls: [[60.5, 10.5, 9, 39]] }, { walls: [[100.5, 0.5, 9, 59]] }] },
        pal: ['run', 'stop', 'car', 'if', 'else'], ops: ['dist'], scripts: ['forever'],
        sol: 'forever{ if:dist<10{ stop:all car:all,red } else{ run:all,fwd,150 car:all,green } }',
        hint: "Cada branca del «si» fa dues coses: moure (o parar) els motors i posar els llums del color que toca.|Cada rama del «si» hace dos cosas: mover (o parar) los motores y poner las luces del color que toca." },
      { k: 'robo', ph: 'repte', q: "<b>A trams.</b> Tram 1: segueix la cinta. Tram 2: atura't a entre 4 i 12 cm de la caixa. La caixa canvia de lloc a cada pista: el mateix programa a les <b>3 pistes</b>!|<b>Por tramos.</b> Tramo 1: sigue la cinta. Tramo 2: párate a entre 4 y 12 cm de la caja. La caja cambia de sitio en cada pista: ¡el mismo programa en las <b>3 pistas</b>!",
        w: { w: 120, h: 80, bot: [15, 65, 90], lines: [{ p: [[15, 65], [45, 65], [55, 55], [55, 35], [65, 25], [115, 25]] }], walls: [[90.5, 20.5, 9, 9]], goal: [{ k: 'near', min: 4, max: 12 }, { k: 'nohit' }, { k: 'dist', min: 60 }], time: 25,
          alts: [{ walls: [[80.5, 20.5, 9, 9]] }, { walls: [[110.5, 20.5, 9, 9]] }] },
        pal: ['run', 'stop', 'patrol', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R'], scripts: ['start', 'forever'],
        sol: 'forever{ if:dist<10{ stop:all } else{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } } }',
        hint: "Primer fes el tram 1 (seguir la cinta). Després posa tot el seguidor dins del «si no» d'un «si distància &lt; 10: atura't».|Primero haz el tramo 1 (seguir la cinta). Después pon todo el seguidor dentro del «si no» de un «si distancia &lt; 10: párate»." },
      { k: 'rdesign', ph: 'crea', q: "Ara que ja l'has programada, <b>millora la teva missió</b>: era massa fàcil? Hi falta un revolt, una caixa o una llauna? Fes-ne la <b>versió 2</b> i desa-la.|Ahora que ya la has programado, <b>mejora tu misión</b>: ¿era demasiado fácil? ¿Le falta una curva, una caja o una lata? Haz la <b>versión 2</b> y guárdala.",
        crit: ['Té una millora: un obstacle, un revolt, una llauna…|Tiene una mejora: un obstáculo, una curva, una lata…', 'Continua tenint solució|Sigue teniendo solución'],
        w: { w: 120, h: 80 }, slot: 'k8' },
      { k: 'rmybuild', ph: 'crea', q: "Programa la <b>versió 2</b> de <b>«{nom}»</b>. Fes servir llums de depuració per trobar els errors i, quan funcioni, treu-los o deixa'ls com a senyal per al públic.|Programa la <b>versión 2</b> de <b>«{nom}»</b>. Usa luces de depuración para encontrar los errores y, cuando funcione, quítalas o déjalas como señal para el público.",
        crit: ['El robot compleix la missió nova|El robot cumple la misión nueva', 'Fa servir almenys un sensor|Usa al menos un sensor', "Has provat i millorat el programa més d'una vegada|Has probado y mejorado el programa más de una vez"],
        pal: ['run', 'stop', 'patrol', 'wait', 'car', 'under', 'note', 'icon', 'num', 'clear', 'set', 'change', 'calc', 'rep', 'while', 'until', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R', 'aL', 'aM', 'aR', 'lL', 'lR', 'A', 'B'], scripts: ['start', 'forever', 'A', 'B'], vars: ['v', 'n'], varNames: { v: 'velocitat|velocidad', n: 'comptador|contador' },
        hint: "Canvia una sola cosa cada vegada i torna-ho a provar: així sabràs què ha arreglat el problema.|Cambia una sola cosa cada vez y vuelve a probar: así sabrás qué ha arreglado el problema.", slot: 'k8' },
      { k: 'quiz', ph: 'tanca', q: "Per què va bé programar una missió llarga a trams?|¿Por qué va bien programar una misión larga por tramos?",
        opts: ["Perquè pots provar cada tros i saber on és l'error|Porque puedes probar cada trozo y saber dónde está el error", "Perquè el robot va més de pressa|Porque el robot va más deprisa", "Perquè fa servir menys piles|Porque usa menos pilas"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Quin és el cicle de l'enginyer/a?|¿Cuál es el ciclo del ingeniero/a?",
        opts: ["Planifica → Programa → Prova → Millora (i torna-hi)|Planifica → Programa → Prueba → Mejora (y otra vez)", "Programa i ja està|Programa y ya está", "Prova → Planifica → Programa|Prueba → Planifica → Programa"], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 3 · Del simulador al robot de veritat ---------- */
  { id: 'k8-3', t: 'Del simulador al robot de veritat|Del simulador al robot de verdad', min: 45, badge: 'k_real',
    learn: ["El botó &lt;/&gt; dona el programa en JavaScript per enganxar-lo a MakeCode i descarregar-lo a la micro:bit.|El botón &lt;/&gt; da el programa en JavaScript para pegarlo en MakeCode y descargarlo en la micro:bit.",
      "Al món real, les piles, el terra i els motors canvien una mica el que fa el robot: per això es calibra.|En el mundo real, las pilas, el suelo y los motores cambian un poco lo que hace el robot: por eso se calibra.",
      "Calibrar és mesurar, calcular i ajustar; els programes amb sensors s'adapten sols.|Calibrar es medir, calcular y ajustar; los programas con sensores se adaptan solos."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "La setmana passada vas fer servir llums de depuració. Per a què serveixen?|La semana pasada usaste luces de depuración. ¿Para qué sirven?",
        opts: ["Per veure què «pensa» el robot i trobar l'error|Para ver qué «piensa» el robot y encontrar el error", "Perquè el robot vagi més de pressa|Para que el robot vaya más deprisa", "Per gastar menys piles|Para gastar menos pilas"], a: 0 },
      { k: 'story', ph: 'missio', who: 'both', scene: 'taller', title: 'Els robots de veritat|Los robots de verdad',
        t: "Al taller del museu esperen els <b>Maqueen de veritat</b>, amb les piles carregades. El simulador és una còpia molt fidel… però el món real té sorpreses: piles que es gasten, terres que llisquen, motors que no són bessons. Avui passaràs el teu programa al robot i l'ajustaràs com un enginyer/a.|En el taller del museo esperan los <b>Maqueen de verdad</b>, con las pilas cargadas. El simulador es una copia muy fiel… pero el mundo real tiene sorpresas: pilas que se gastan, suelos que resbalan, motores que no son gemelos. Hoy pasarás tu programa al robot y lo ajustarás como un ingeniero/a." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'MakeCode|MakeCode', t: 'Del simulador a la micro:bit|Del simulador a la micro:bit', anim: 'k8export',
          x: "Al programa de cada repte hi ha el botó <b>&lt;/&gt;</b>: et dona el mateix programa escrit en <b>JavaScript</b>. A <b>makecode.microbit.org</b>: nou projecte → Extensions → «maqueen» → JavaScript → enganxa-hi el codi. Torna a «Blocs» i hi veuràs els mateixos blocs. Amb «Descarrega» tens un fitxer <b>.hex</b> que s'arrossega a la unitat MICROBIT.|En el programa de cada reto está el botón <b>&lt;/&gt;</b>: te da el mismo programa escrito en <b>JavaScript</b>. En <b>makecode.microbit.org</b>: nuevo proyecto → Extensiones → «maqueen» → JavaScript → pega el código. Vuelve a «Bloques» y verás los mismos bloques. Con «Descargar» tienes un archivo <b>.hex</b> que se arrastra a la unidad MICROBIT.",
          tip: "Si l'ordinador ho permet, MakeCode pot descarregar directament a la micro:bit pel cable USB.|Si el ordenador lo permite, MakeCode puede descargar directamente en la micro:bit por el cable USB." },
        { k: 'Dos llenguatges|Dos lenguajes', t: 'Blocs i JavaScript: el mateix programa|Bloques y JavaScript: el mismo programa',
          robo: { w: { w: 120, h: 60, bot: [15, 30, 90], walls: [[80.5, 10.5, 9, 39]] }, prog: 'forever{ if:dist<10{ stop:all } else{ run:all,fwd,150 } }' },
          x: "Cada bloc té la seva línia de JavaScript. «per sempre» és <code>basic.forever</code>; «si distància &lt; 10» és <code>if (Maqueen_V5.Ultrasonic() &lt; 10)</code>; «atura els dos» és <code>Maqueen_V5.motorStop(Maqueen_V5.Motors.All)</code>. Són dues maneres d'escriure el mateix: molts programadors i programadores professionals escriuen en text.|Cada bloque tiene su línea de JavaScript. «para siempre» es <code>basic.forever</code>; «si distancia &lt; 10» es <code>if (Maqueen_V5.Ultrasonic() &lt; 10)</code>; «para los dos» es <code>Maqueen_V5.motorStop(Maqueen_V5.Motors.All)</code>. Son dos maneras de escribir lo mismo: muchos programadores y programadoras profesionales escriben en texto.",
          tip: "Toca el botó &lt;/&gt; de qualsevol repte per veure el teu programa en JavaScript.|Toca el botón &lt;/&gt; de cualquier reto para ver tu programa en JavaScript." },
        { k: 'El món real|El mundo real', t: 'Per què el robot real fa una mica diferent?|¿Por qué el robot real hace algo diferente?', anim: 'k8drift',
          x: "Amb les piles mig gastades, els motors van més lents. En una catifa, les rodes llisquen. I els dos motors mai no són ben bessons: un pot girar una mica més que l'altre i el robot es desvia. Per això un programa de <b>temps fixos</b> s'atura abans d'hora o es torça, i un programa amb <b>sensors</b> s'atura on toca.|Con las pilas medio gastadas, los motores van más lentos. En una alfombra, las ruedas resbalan. Y los dos motores nunca son del todo gemelos: uno puede girar un poco más que el otro y el robot se desvía. Por eso un programa de <b>tiempos fijos</b> se para antes de hora o se tuerce, y un programa con <b>sensores</b> se para donde toca." },
        { k: 'Calibrar|Calibrar', t: 'Mesura, calcula, ajusta|Mide, calcula, ajusta', anim: 'k8calib',
          x: "<span class='hl'>Calibrar</span> és ajustar els números del programa al teu robot. Fes-lo avançar 4 segons i mesura amb el metre: si ha fet 52 cm, va a 52 ÷ 4 = <b>13 cm/s</b>. Per fer 78 cm li calen 78 ÷ 13 = 6 segons: «espera 6000 ms». Amb els girs igual: prova 590 ms i, si gira massa o massa poc, ajusta.|<span class='hl'>Calibrar</span> es ajustar los números del programa a tu robot. Hazlo avanzar 4 segundos y mide con el metro: si ha hecho 52 cm, va a 52 ÷ 4 = <b>13 cm/s</b>. Para hacer 78 cm necesita 78 ÷ 13 = 6 segundos: «espera 6000 ms». Con los giros igual: prueba 590 ms y, si gira demasiado o demasiado poco, ajusta.",
          tip: "Al simulador, a 150, el Maqueen fa uns 15,6 cm/s. El teu pot anar una mica diferent.|En el simulador, a 150, el Maqueen hace unos 15,6 cm/s. El tuyo puede ir un poco diferente." },
        { k: 'Compte!|¡Cuidado!', t: 'Temps o sensor?|¿Tiempo o sensor?',
          robo: { w: { w: 120, h: 60, bot: [15, 30, 90], lines: [{ p: [[80, 8], [80, 52]] }], zones: [{ id: 'm', r: [62, 15, 24, 30], col: 'yellow', label: 'META|META' }] }, prog: 'forever{ if:M=1{ stop:all car:all,green } else{ run:all,fwd,120 } }' },
          x: "Aquest robot no sap quants segons ha d'anar: avança <b>fins que</b> el sensor del mig troba la cinta de meta. Amb piles noves o gastades, en un terra o en un altre, sempre s'atura a la cinta. Quan passis el programa al robot real, canvia les esperes llargues per sensors sempre que puguis.|Este robot no sabe cuántos segundos tiene que ir: avanza <b>hasta que</b> el sensor del medio encuentra la cinta de meta. Con pilas nuevas o gastadas, en un suelo o en otro, siempre se para en la cinta. Cuando pases el programa al robot real, cambia las esperas largas por sensores siempre que puedas.",
          bad: "Si funciona al simulador, al robot real farà exactament el mateix.|Si funciona en el simulador, en el robot real hará exactamente lo mismo.", good: "Al robot real es calibra, i els sensors fan el programa més fiable.|En el robot real se calibra, y los sensores hacen el programa más fiable." }
      ] },
      { k: 'quiz', ph: 'mans', q: "Llegeix aquesta línia de JavaScript de MakeCode: <code>Maqueen_V5.motorRun(Maqueen_V5.Motors.All, Maqueen_V5.Dir.CW, 150)</code>. <b>Quin bloc és?</b>|Lee esta línea de JavaScript de MakeCode: <code>Maqueen_V5.motorRun(Maqueen_V5.Motors.All, Maqueen_V5.Dir.CW, 150)</code>. <b>¿Qué bloque es?</b>",
        opts: ["Motor els dos endavant a velocitat 150|Motor los dos adelante a velocidad 150", "Atura el motor esquerre|Para el motor izquierdo", "Espera 150 ms|Espera 150 ms"], a: 0,
        ex: "<code>motorRun</code> engega motors; <code>All</code> vol dir els dos; <code>CW</code> és endavant (<code>CCW</code> seria enrere) i 150 és la velocitat.|<code>motorRun</code> enciende motores; <code>All</code> quiere decir los dos; <code>CW</code> es adelante (<code>CCW</code> sería atrás) y 150 es la velocidad." },
      { k: 'seq', ph: 'mans', q: "Com passes el programa del simulador al Maqueen de veritat? <b>Ordena els passos.</b>|¿Cómo pasas el programa del simulador al Maqueen de verdad? <b>Ordena los pasos.</b>",
        items: ["Toco &lt;/&gt; al simulador i copio el codi|Toco &lt;/&gt; en el simulador y copio el código", "A MakeCode: nou projecte i extensió «maqueen»|En MakeCode: nuevo proyecto y extensión «maqueen»", "Passo a JavaScript i enganxo el codi|Paso a JavaScript y pego el código", "Descarrego el .hex a la micro:bit amb el cable USB|Descargo el .hex en la micro:bit con el cable USB", "Desconnecto el cable, poso el robot a terra i l'encenc|Desconecto el cable, pongo el robot en el suelo y lo enciendo"],
        ex: "Primer el codi, després MakeCode, la descàrrega i, al final, el robot a terra. Sense l'extensió «maqueen», MakeCode no entén les ordres del robot.|Primero el código, después MakeCode, la descarga y, al final, el robot en el suelo. Sin la extensión «maqueen», MakeCode no entiende las órdenes del robot." },
      { k: 'unplug', ph: 'mans', ico: '📏', title: 'Calibra les teves passes|Calibra tus pasos', t: "A casa, en un passadís, fes de robot que es calibra.|En casa, en un pasillo, haz de robot que se calibra.",
        steps: ["Camina 10 passes normals i mesura amb un metre quants centímetres has fet.|Camina 10 pasos normales y mide con un metro cuántos centímetros has hecho.",
          "Calcula quant fa una passa: divideix entre 10.|Calcula cuánto mide un paso: divide entre 10.",
          "Tria un objecte de casa i calcula quantes passes hi ha fins a ell. Després, comprova-ho caminant.|Elige un objeto de casa y calcula cuántos pasos hay hasta él. Después, compruébalo caminando.",
          "Ara camina amb passes de formiga: ha canviat la calibració? Per què?|Ahora camina con pasos de hormiga: ¿ha cambiado la calibración? ¿Por qué?"],
        tip: "Com el robot amb les piles gastades: si canvien les passes, cal tornar a calibrar.|Como el robot con las pilas gastadas: si cambian los pasos, hay que volver a calibrar." },
      { k: 'quiz', ph: 'prova', q: "El vostre Maqueen, a velocitat 150, ha fet <b>52 cm en 4 segons</b>. Voleu que avanci <b>78 cm</b>. Quina espera hi posareu?|Vuestro Maqueen, a velocidad 150, ha hecho <b>52 cm en 4 segundos</b>. Queréis que avance <b>78 cm</b>. ¿Qué espera pondréis?",
        opts: ['6000 ms|6000 ms', '4000 ms|4000 ms', '7800 ms|7800 ms'], a: 0,
        ex: "52 ÷ 4 = 13 cm cada segon. 78 ÷ 13 = 6 segons, és a dir, 6000 ms.|52 ÷ 4 = 13 cm cada segundo. 78 ÷ 13 = 6 segundos, es decir, 6000 ms." },
      { k: 'rpredict', ph: 'prova', q: "Un gir de 590 ms fa uns 90°. Aquest programa gira només <b>295 ms</b> (la meitat) i després avança. <b>On acabarà?</b>|Un giro de 590 ms hace unos 90°. Este programa gira solo <b>295 ms</b> (la mitad) y después avanza. <b>¿Dónde terminará?</b>",
        w: { w: 120, h: 80, bot: [20, 65, 90], marks: { A: [52, 31], B: [67, 65], C: [20, 18] } }, scripts: ['start'],
        prog: 'start{ run:L,back,100 run:R,fwd,100 wait:295 stop:all wait:300 run:all,fwd,150 wait:3000 stop:all }', a: 'A',
        ex: "La meitat del temps fa la meitat del gir: uns 45°. Mira en diagonal, amunt i a la dreta, i avança en aquesta direcció.|La mitad del tiempo hace la mitad del giro: unos 45°. Mira en diagonal, arriba y a la derecha, y avanza en esa dirección." },
      { k: 'robo', ph: 'prova', q: "<b>Calibra el gir.</b> El robot mira a la dreta. Fes-lo girar sobre si mismo fins que miri <b>avall</b> (90° cap a la dreta) i que s'aturi. Prova un temps, mira l'angle i ajusta.|<b>Calibra el giro.</b> El robot mira a la derecha. Hazlo girar sobre sí mismo hasta que mire <b>hacia abajo</b> (90° hacia la derecha) y que se pare. Prueba un tiempo, mira el ángulo y ajusta.",
        w: { w: 80, h: 60, bot: [40, 30, 90], goal: [{ k: 'face', h: 180, tol: 8 }, { k: 'stopped' }], time: 6 },
        pal: ['run', 'stop', 'wait'], ops: [], scripts: ['start'],
        sol: 'start{ run:L,fwd,100 run:R,back,100 wait:590 stop:all }',
        hint: "Per girar a la dreta: motor esquerre endavant i dret enrere, a 100. Si gira massa, escurça l'espera; si es queda curt, allarga-la.|Para girar a la derecha: motor izquierdo adelante y derecho atrás, a 100. Si gira demasiado, acorta la espera; si se queda corto, alárgala." },
      { k: 'rspot', ph: 'investiga', q: "Aquest programa funciona perfecte al simulador. Al robot real, amb les piles gastades, <b>s'atura abans de la meta</b>. <b>Toca el bloc que depèn de les piles</b> i que convindria canviar per un sensor.|Este programa funciona perfecto en el simulador. En el robot real, con las pilas gastadas, <b>se para antes de la meta</b>. <b>Toca el bloque que depende de las pilas</b> y que convendría cambiar por un sensor.",
        w: { w: 120, h: 60, bot: [15, 30, 90], lines: [{ p: [[80, 8], [80, 52]] }], zones: [{ id: 'm', r: [62, 15, 24, 30], col: 'yellow', label: 'META|META' }] }, scripts: ['start'],
        prog: 'start{ car:all,green run:all,fwd,120 wait:5000! stop:all icon:happy }',
        yes: "Exacte! L'espera suposa que el robot sempre va igual de ràpid. Amb «repeteix fins que línia M = 1» s'aturaria a la cinta.|¡Exacto! La espera supone que el robot siempre va igual de rápido. Con «repite hasta que línea M = 1» se pararía en la cinta.",
        ex: "És l'espera de 5000 ms: amb les piles gastades, en 5 segons el robot fa menys camí. Si en lloc d'esperar avancés «fins que línia M = 1», s'aturaria a la cinta de meta.|Es la espera de 5000 ms: con las pilas gastadas, en 5 segundos el robot hace menos camino. Si en lugar de esperar avanzara «hasta que línea M = 1», se pararía en la cinta de meta." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de robot amb les piles gastades! Camina al teu lloc molt a poc a poc… ara amb piles noves, de pressa… ara en una catifa que llisca (passes curtes i relliscoses)… i atura't en sec quan algú digui «cinta!».|¡Haz de robot con las pilas gastadas! Camina en tu sitio muy despacio… ahora con pilas nuevas, deprisa… ahora en una alfombra que resbala (pasos cortos y resbaladizos)… ¡y párate en seco cuando alguien diga «cinta»!" },
      { k: 'robo', ph: 'repte', q: "<b>A prova de piles.</b> Atura't a la <b>META</b>, sobre la cinta. A cada pista la cinta és en un lloc diferent, com si el robot anés més ràpid o més lent: el mateix programa ha de funcionar a les <b>3 pistes</b>.|<b>A prueba de pilas.</b> Párate en la <b>META</b>, sobre la cinta. En cada pista la cinta está en un sitio diferente, como si el robot fuera más rápido o más lento: el mismo programa tiene que funcionar en las <b>3 pistas</b>.",
        w: { w: 120, h: 60, bot: [15, 30, 90], lines: [{ p: [[80, 8], [80, 52]] }], zones: [{ id: 'm', r: [62, 15, 24, 30], col: 'yellow', label: 'META|META' }], goal: [{ k: 'zone', id: 'm', stop: true }, { k: 'nohit' }], time: 14,
          alts: [{ lines: [{ p: [[55, 8], [55, 52]] }], zones: [{ id: 'm', r: [37, 15, 24, 30], col: 'yellow', label: 'META|META' }] }, { lines: [{ p: [[100, 8], [100, 52]] }], zones: [{ id: 'm', r: [82, 15, 24, 30], col: 'yellow', label: 'META|META' }] }] },
        pal: ['run', 'stop', 'wait', 'until', 'if', 'else'], ops: ['M'], scripts: ['start', 'forever'],
        sol: 'start{ until:M=1{ run:all,fwd,120 } stop:all }',
        hint: "Amb temps no funcionarà a totes. Fes servir «repeteix fins que línia M = 1» amb el motor a dins, i després «atura».|Con tiempo no funcionará en todas. Usa «repite hasta que línea M = 1» con el motor dentro, y después «para»." },
      { k: 'robo', ph: 'repte', q: "<b>La pista de l'aula.</b> És la pista que construireu a terra amb cinta. Segueix la cinta, atura't a entre 4 i 12 cm de la caixa i, quan t'aturis, mostra la icona <b>content</b> a la micro:bit. La caixa pot estar en dos llocs.|<b>La pista del aula.</b> Es la pista que construiréis en el suelo con cinta. Sigue la cinta, párate a entre 4 y 12 cm de la caja y, cuando te pares, muestra el icono <b>contento</b> en la micro:bit. La caja puede estar en dos sitios.",
        w: { w: 120, h: 80, bot: [15, 60, 90], lines: [{ p: [[15, 60], [50, 60], [60, 50], [60, 30], [70, 20], [115, 20]] }], walls: [[100.5, 10.5, 9, 9]], goal: [{ k: 'near', min: 4, max: 12 }, { k: 'nohit' }, { k: 'icon', ic: 'happy' }], time: 25, alts: [{ walls: [[90.5, 10.5, 9, 9]] }] },
        pal: ['run', 'stop', 'patrol', 'icon', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R'], scripts: ['start', 'forever'],
        sol: 'forever{ if:dist<10{ stop:all icon:happy } else{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } } }',
        hint: "És com el repte dels trams de la setmana passada, amb un bloc més: la icona, dins de la branca que atura el robot.|Es como el reto de los tramos de la semana pasada, con un bloque más: el icono, dentro de la rama que para el robot." },
      { k: 'rdesign', ph: 'crea', q: "Penseu que la vostra missió es construirà a terra amb cinta i caixes de veritat. <b>Adapta-la</b> perquè es pugui fer a l'aula: la cinta amb revolts suaus, les caixes on hi hagi caixes… i desa-la.|Pensad que vuestra misión se construirá en el suelo con cinta y cajas de verdad. <b>Adáptala</b> para que se pueda hacer en el aula: la cinta con curvas suaves, las cajas donde haya cajas… y guárdala.",
        crit: ["Es pot construir amb el material de l'aula|Se puede construir con el material del aula", 'Continua tenint solució|Sigue teniendo solución'],
        w: { w: 120, h: 80 }, slot: 'k8' },
      { k: 'rmybuild', ph: 'crea', q: "Fes la <b>versió per al robot real</b> de <b>«{nom}»</b>: canvia les esperes llargues per sensors sempre que puguis. Quan funcioni, toca <b>&lt;/&gt;</b>, copia el codi i passa'l al Maqueen amb MakeCode.|Haz la <b>versión para el robot real</b> de <b>«{nom}»</b>: cambia las esperas largas por sensores siempre que puedas. Cuando funcione, toca <b>&lt;/&gt;</b>, copia el código y pásalo al Maqueen con MakeCode.",
        crit: ['El robot compleix la missió al simulador|El robot cumple la misión en el simulador', 'Fa servir almenys un sensor|Usa al menos un sensor', 'Has copiat el codi amb &lt;/&gt; per passar-lo a MakeCode|Has copiado el código con &lt;/&gt; para pasarlo a MakeCode'],
        check(P) { const S = ['dist', 'L', 'M', 'R', 'aL', 'aM', 'aR', 'lL', 'lR'], op = o => !!o && typeof o === 'object' && S.includes(o.r), cd = c => !!c && (c.and || c.or ? (c.and || c.or).some(cd) : op(c.a) || op(c.b)), w = l => (l || []).some(b => b.k === 'patrol' || cd(b.c) || [b.s, b.ms, b.a, b.y, b.n, b.v].some(op) || w(Array.isArray(b.b) ? b.b : null) || w(b.e));
          return Object.values(P).some(w) ? null : "Funciona al simulador! Però al robot real, amb només temps, pot fallar: fes servir almenys un sensor (distància, línia o llum).|¡Funciona en el simulador! Pero en el robot real, con solo tiempo, puede fallar: usa al menos un sensor (distancia, línea o luz)."; },
        pal: ['run', 'stop', 'patrol', 'wait', 'car', 'under', 'note', 'icon', 'num', 'clear', 'set', 'change', 'calc', 'rep', 'while', 'until', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R', 'aL', 'aM', 'aR', 'lL', 'lR', 'A', 'B'], scripts: ['start', 'forever', 'A', 'B'], vars: ['v', 'n'], varNames: { v: 'velocitat|velocidad', n: 'comptador|contador' },
        hint: "Busca les esperes que diuen «quant temps» i pregunta't: hi ha un sensor que sàpiga «quan» parar? Una caixa (distància) o una cinta (línia)?|Busca las esperas que dicen «cuánto tiempo» y pregúntate: ¿hay un sensor que sepa «cuándo» parar? ¿Una caja (distancia) o una cinta (línea)?", slot: 'k8' },
      { k: 'quiz', ph: 'tanca', q: "Per què el robot de veritat no fa exactament el mateix que el del simulador?|¿Por qué el robot de verdad no hace exactamente lo mismo que el del simulador?",
        opts: ["Per les piles, el terra i els motors, que no són perfectes|Por las pilas, el suelo y los motores, que no son perfectos", "Perquè MakeCode canvia el programa|Porque MakeCode cambia el programa", "Perquè el robot real és d'una altra marca|Porque el robot real es de otra marca"], a: 0,
        ex: "El programa és el mateix; el que canvia és el món. Per això es calibra i es fan servir sensors.|El programa es el mismo; lo que cambia es el mundo. Por eso se calibra y se usan sensores." },
      { k: 'quiz', ph: 'tanca', q: "Què vol dir <b>calibrar</b> el robot?|¿Qué quiere decir <b>calibrar</b> el robot?",
        opts: ["Mesurar què fa de veritat i ajustar els números del programa|Medir lo que hace de verdad y ajustar los números del programa", "Canviar-li les rodes|Cambiarle las ruedas", "Esborrar el programa i fer-ne un de nou|Borrar el programa y hacer uno nuevo"], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 4 · Presentació i diploma ---------- */
  { id: 'k8-4', t: 'Presentació i diploma|Presentación y diploma', min: 45, proj: true, badge: 'k_enginyer',
    learn: ["Una bona presentació explica la missió, com funciona el robot, un problema resolt i ho demostra.|Una buena presentación explica la misión, cómo funciona el robot, un problema resuelto y lo demuestra.",
      "Un bon comentari diu una cosa que agrada i una idea per millorar.|Un buen comentario dice algo que gusta y una idea para mejorar.",
      "Un robot sent, pensa i actua: i ara tu saps programar-lo de principi a fi.|Un robot siente, piensa y actúa: y ahora tú sabes programarlo de principio a fin."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "La setmana passada vas calibrar el robot. Si el robot real <b>gira massa</b> amb una espera de 590 ms, què fas?|La semana pasada calibraste el robot. Si el robot real <b>gira demasiado</b> con una espera de 590 ms, ¿qué haces?",
        opts: ["Escurço l'espera del gir i ho torno a provar|Acorto la espera del giro y vuelvo a probar", "Allargo l'espera|Alargo la espera", "Canvio la velocitat a 255|Cambio la velocidad a 255"], a: 0 },
      { k: 'story', ph: 'missio', who: 'both', scene: 'poble', title: 'El gran dia de la Mostra|El gran día de la Muestra',
        t: "La plaça del poble s'ha omplert de taules, pistes de cinta i famílies curioses: avui és la <b>Mostra de Robots</b>! Cada enginyer/a presentarà la seva missió, un company/a la provarà i, al final, rebràs el <b>diploma</b> del curs de robòtica.|La plaza del pueblo se ha llenado de mesas, pistas de cinta y familias curiosas: ¡hoy es la <b>Muestra de Robots</b>! Cada ingeniero/a presentará su misión, un compañero/a la probará y, al final, recibirás el <b>diploma</b> del curso de robótica." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'happy', t: "BIP BIP! Jo també estic nerviós… i això que només soc d'una illa de caselles! Recorda: no cal que tot surti perfecte. Al públic li agrada saber <b>com ho has pensat</b> i què has après pel camí.|¡BIP BIP! Yo también estoy nervioso… ¡y eso que solo soy de una isla de casillas! Recuerda: no hace falta que todo salga perfecto. Al público le gusta saber <b>cómo lo has pensado</b> y qué has aprendido por el camino." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Presentar|Presentar', t: 'Quatre parts i una demo|Cuatro partes y una demo', anim: 'k8pitch',
          x: "Una presentació d'enginyer/a té quatre parts: <b>1)</b> la missió (què ha de fer el robot), <b>2)</b> com funciona (quins sensors fa servir i què decideix el programa), <b>3)</b> un problema que vas tenir i com el vas resoldre i <b>4)</b> la demostració. En dos minuts n'hi ha prou!|Una presentación de ingeniero/a tiene cuatro partes: <b>1)</b> la misión (qué tiene que hacer el robot), <b>2)</b> cómo funciona (qué sensores usa y qué decide el programa), <b>3)</b> un problema que tuviste y cómo lo resolviste y <b>4)</b> la demostración. ¡En dos minutos es suficiente!",
          tip: "Parla mirant el públic, no la pantalla.|Habla mirando al público, no a la pantalla." },
        { k: 'Com funciona|Cómo funciona', t: 'Explica-ho amb sent, pensa i actua|Explícalo con siente, piensa y actúa',
          robo: { w: { w: 120, h: 80, bot: [15, 60, 90], lines: [{ p: [[15, 60], [50, 60], [60, 50], [60, 30], [70, 20], [115, 20]] }], walls: [[100.5, 10.5, 9, 9]] }, prog: 'start{ icon:heart } forever{ if:dist<10{ stop:all car:all,green } else{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } } }' },
          x: "Per explicar el programa, fes servir el cicle de qualsevol robot: «El meu robot <b>sent</b> la cinta amb els sensors de línia i la caixa amb els ultrasons. <b>Pensa</b>: si la caixa és a menys de 10 cm, s'ha d'aturar. I <b>actua</b>: gira les rodes i encén els llums verds.»|Para explicar el programa, usa el ciclo de cualquier robot: «Mi robot <b>siente</b> la cinta con los sensores de línea y la caja con los ultrasonidos. <b>Piensa</b>: si la caja está a menos de 10 cm, se tiene que parar. Y <b>actúa</b>: gira las ruedas y enciende las luces verdes.»" },
        { k: 'Comentaris|Comentarios', t: 'Comentaris que ajuden|Comentarios que ayudan', anim: 'k8cycle',
          x: "Quan provis la missió d'un company/a, fes un <span class='hl'>comentari que ajudi</span>: <b>una cosa que t'ha agradat</b> i <b>una idea per millorar</b>. «M'agrada el revolt del final; potser la meta podria ser més lluny.» Els comentaris són el combustible de la volta següent del cicle.|Cuando pruebes la misión de un compañero/a, haz un <span class='hl'>comentario que ayude</span>: <b>algo que te ha gustado</b> y <b>una idea para mejorar</b>. «Me gusta la curva del final; quizá la meta podría estar más lejos.» Los comentarios son el combustible de la siguiente vuelta del ciclo.",
          bad: "«És horrible» o «està bé» i prou.|«Es horrible» o «está bien» y ya está.", good: "«M'agrada… i potser podries…»|«Me gusta… y quizá podrías…»" },
        { k: 'El viatge|El viaje', t: 'Tot el que ja saps fer|Todo lo que ya sabes hacer',
          robo: { w: { w: 120, h: 80, bot: [15, 45, 90], lines: [{ p: [[15, 45], [45, 45], [55, 35], [65, 45], [105, 45]] }], walls: [[110.5, 30.5, 9, 29]], dark: true }, prog: 'start{ under:all,blue note:C4,1/4 note:E4,1/4 note:G4,1/4 } forever{ if:dist<10{ stop:all icon:happy car:all,green } else{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } } }' },
          x: "Motors i velocitat, girs i calibratge, ultrasons, sensors de línia, llum i so, variables, missions… En aquest curs has après a fer que un robot <b>senti, pensi i actuï</b>. I ara ets capaç d'inventar una missió i programar-la de principi a fi.|Motores y velocidad, giros y calibración, ultrasonidos, sensores de línea, luz y sonido, variables, misiones… En este curso has aprendido a hacer que un robot <b>sienta, piense y actúe</b>. Y ahora eres capaz de inventar una misión y programarla de principio a fin." }
      ] },
      { k: 'seq', ph: 'mans', q: "Prepara el teu guió. <b>Ordena les parts</b> de la presentació.|Prepara tu guion. <b>Ordena las partes</b> de la presentación.",
        items: ["La missió: «El meu robot ha de…»|La misión: «Mi robot tiene que…»", "Com funciona: sensors, decisions i motors|Cómo funciona: sensores, decisiones y motores", "Un problema que vaig tenir i com el vaig resoldre|Un problema que tuve y cómo lo resolví", "La demostració davant del públic|La demostración delante del público"],
        ex: "Primer el públic ha d'entendre què veurà; així, quan facis la demo, tothom sabrà què mirar.|Primero el público tiene que entender qué verá; así, cuando hagas la demo, todo el mundo sabrá qué mirar." },
      { k: 'quiz', ph: 'mans', q: "En Pol ha provat la missió de la Júlia. <b>Quin comentari l'ajudarà més?</b>|Pol ha probado la misión de Júlia. <b>¿Qué comentario la ayudará más?</b>",
        opts: ["«M'agraden els llums de la meta. Potser una caixa al revolt la faria més interessant.»|«Me gustan las luces de la meta. Quizá una caja en la curva la haría más interesante.»", "«Està bé.»|«Está bien.»", "«La meva és molt millor.»|«La mía es mucho mejor.»"], a: 0,
        ex: "Un bon comentari és concret i amable: diu què funciona i proposa una idea.|Un buen comentario es concreto y amable: dice qué funciona y propone una idea." },
      { k: 'robo', ph: 'repte', q: "<b>L'assaig general.</b> Una demostració per al públic: en començar, la micro:bit mostra un cor i sonen les notes <b>do, mi, sol</b>. Després el robot segueix la cinta i s'atura davant la caixa amb els llums <b>verds</b>.|<b>El ensayo general.</b> Una demostración para el público: al empezar, la micro:bit muestra un corazón y suenan las notas <b>do, mi, sol</b>. Después el robot sigue la cinta y se para delante de la caja con las luces <b>verdes</b>.",
        w: { w: 120, h: 80, bot: [15, 60, 90], lines: [{ p: [[15, 60], [50, 60], [60, 50], [60, 30], [70, 20], [115, 20]] }], walls: [[100.5, 10.5, 9, 9]], goal: [{ k: 'notes', n: ['C4', 'E4', 'G4'] }, { k: 'near', min: 4, max: 12 }, { k: 'nohit' }, { k: 'car', c: 'green' }], time: 25, alts: [{ walls: [[90.5, 10.5, 9, 9]] }] },
        pal: ['run', 'stop', 'patrol', 'car', 'note', 'icon', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R'], scripts: ['start', 'forever'],
        sol: 'start{ icon:heart note:C4,1/2 note:E4,1/2 note:G4,1/2 } forever{ if:dist<10{ stop:all car:all,green } else{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } } }',
        hint: "La benvinguda va a «en iniciar»; el seguidor i la parada, a «per sempre», com al repte de la pista de l'aula.|La bienvenida va en «al iniciar»; el seguidor y la parada, en «para siempre», como en el reto de la pista del aula." },
      { k: 'rdesign', ph: 'crea', q: "<b>Últims retocs!</b> Deixa la teva missió a punt per a la Mostra: el nom, les comprovacions, cada caixa al seu lloc. Si ja t'agrada com està, només cal que la tornis a desar.|<b>¡Últimos retoques!</b> Deja tu misión lista para la Muestra: el nombre, las comprobaciones, cada caja en su sitio. Si ya te gusta como está, solo tienes que volver a guardarla.",
        crit: ['Té solució i està al punt|Tiene solución y está en su punto', "Té un nom que t'agrada|Tiene un nombre que te gusta"],
        w: { w: 120, h: 80 }, slot: 'k8' },
      { k: 'story', ph: 'crea', who: 'numi', title: 'Canvi de lloc!|¡Cambio de sitio!',
        t: "Ara us aixequeu i <b>canvieu d'ordinador</b> amb un company/a. En el pas següent veuràs la missió d'una altra persona: tu en seràs el <b>provador/a</b>. L'autor/a pot mirar, però no pot tocar ni donar la solució!|Ahora os levantáis y <b>cambiáis de ordenador</b> con un compañero/a. En el paso siguiente verás la misión de otra persona: tú serás el <b>probador/a</b>. El autor/a puede mirar, ¡pero no puede tocar ni dar la solución!" },
      { k: 'rmybuild', ph: 'crea', q: "Hola, provador/a! Aquesta és la missió <b>«{nom}»</b>. Mira la pista i les comprovacions, pensa un pla per trams i programa-la.|¡Hola, probador/a! Esta es la misión <b>«{nom}»</b>. Mira la pista y las comprobaciones, piensa un plan por tramos y prográmala.",
        crit: ["Resol la missió sense que l'autor/a et digui la solució|Resuelve la misión sin que el autor/a te diga la solución", "Fixa't en què és fàcil i què costa|Fíjate en qué es fácil y qué cuesta"],
        pal: ['run', 'stop', 'patrol', 'wait', 'car', 'under', 'note', 'icon', 'num', 'clear', 'set', 'change', 'calc', 'rep', 'while', 'until', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R', 'aL', 'aM', 'aR', 'lL', 'lR', 'A', 'B'], scripts: ['start', 'forever', 'A', 'B'], vars: ['v', 'n'], varNames: { v: 'velocitat|velocidad', n: 'comptador|contador' },
        hint: "Llegeix les comprovacions: et diuen exactament què ha d'aconseguir el robot. Comença pel primer tram.|Lee las comprobaciones: te dicen exactamente qué tiene que conseguir el robot. Empieza por el primer tramo.", slot: 'k8' },
      { k: 'review', ph: 'crea', q: "Ara valora la missió, provador/a. Respon amb sinceritat i amabilitat: les teves respostes ajudaran l'autor/a a millorar-la.|Ahora valora la misión, probador/a. Responde con sinceridad y amabilidad: tus respuestas ayudarán al autor/a a mejorarla.",
        items: [
          { q: "Era clar què havia de fer el robot?|¿Estaba claro qué tenía que hacer el robot?", opts: ['Sí, molt clar|Sí, muy claro', 'Més o menys|Más o menos', 'No gaire|No mucho'] },
          { q: 'Com era de difícil?|¿Cómo de difícil era?', opts: ['Massa fàcil|Demasiado fácil', 'Al punt|En su punto', 'Massa difícil|Demasiado difícil'] },
          { q: 'Quin sensor has fet servir?|¿Qué sensor has usado?', opts: ['Ultrasons|Ultrasonidos', 'Línia|Línea', 'Llum|Luz', 'Cap: només temps|Ninguno: solo tiempo'] },
          { q: 'Què milloraries?|¿Qué mejorarías?', opts: ['Més obstacles|Más obstáculos', 'Menys obstacles|Menos obstáculos', 'Una cinta per seguir|Una cinta que seguir', 'Ja està molt bé|Ya está muy bien'] }
        ] },
      { k: 'story', ph: 'crea', who: 'bit', mood: 'wave', title: 'Torneu al vostre lloc|Volved a vuestro sitio',
        t: "Gràcies, provador/a! Abans de tornar al teu ordinador, explica de paraula a l'autor/a <b>una cosa que t'ha agradat</b> i <b>una idea per millorar</b>. Després, torneu cadascú al vostre lloc.|¡Gracias, probador/a! Antes de volver a tu ordenador, explica de palabra al autor/a <b>algo que te ha gustado</b> y <b>una idea para mejorar</b>. Después, volved cada uno a vuestro sitio." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Abans de presentar, estira't com un robot que es desperta: braços amunt (llums encesos), gira el cap a l'esquerra i a la dreta (ultrasons), tres passos endavant i… reverència al públic!|Antes de presentar, estírate como un robot que se despierta: brazos arriba (luces encendidas), gira la cabeza a la izquierda y a la derecha (ultrasonidos), tres pasos adelante y… ¡reverencia al público!" },
      { k: 'rdesign', ph: 'crea', q: "Ja ets al teu lloc. Pensa en el comentari del provador/a i, si t'agrada la idea, <b>aplica-la a la teva missió</b>. Tu decideixes quins canvis la fan millor. Desa-la.|Ya estás en tu sitio. Piensa en el comentario del probador/a y, si te gusta la idea, <b>aplícala a tu misión</b>. Tú decides qué cambios la hacen mejor. Guárdala.",
        crit: ["Has pensat en el comentari del provador/a|Has pensado en el comentario del probador/a", 'Continua tenint solució|Sigue teniendo solución'],
        w: { w: 120, h: 80 }, slot: 'k8' },
      { k: 'rmybuild', ph: 'crea', q: "És el teu torn de presentar <b>«{nom}»</b>! Programa-la (o torna-la a fer), executa-la al projector i explica les quatre parts: la missió, com funciona, un problema resolt i la demo.|¡Es tu turno de presentar <b>«{nom}»</b>! Prográmala (o vuelve a hacerla), ejecútala en el proyector y explica las cuatro partes: la misión, cómo funciona, un problema resuelto y la demo.",
        crit: ['El robot compleix la missió davant de tothom|El robot cumple la misión delante de todo el mundo', "Expliques com funciona amb «sent, pensa i actua»|Explicas cómo funciona con «siente, piensa y actúa»", "Expliques un problema i com el vas resoldre|Explicas un problema y cómo lo resolviste"],
        pal: ['run', 'stop', 'patrol', 'wait', 'car', 'under', 'note', 'icon', 'num', 'clear', 'set', 'change', 'calc', 'rep', 'while', 'until', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R', 'aL', 'aM', 'aR', 'lL', 'lR', 'A', 'B'], scripts: ['start', 'forever', 'A', 'B'], vars: ['v', 'n'], varNames: { v: 'velocitat|velocidad', n: 'comptador|contador' },
        hint: "Si has canviat la pista, revisa els trams que toquen la part nova: segurament només cal ajustar-ne un.|Si has cambiado la pista, revisa los tramos que tocan la parte nueva: seguramente solo hay que ajustar uno.", slot: 'k8' },
      { k: 'diploma', ph: 'tanca', skills: [
        "Saber què és un robot: sent, pensa i actua|Saber qué es un robot: siente, piensa y actúa",
        "Programar motors amb precisió: distàncies, girs i calibratge|Programar motores con precisión: distancias, giros y calibración",
        "Fer servir els ultrasons per parar i esquivar obstacles|Usar los ultrasonidos para parar y esquivar obstáculos",
        "Seguir línies amb els sensors de sota|Seguir líneas con los sensores de abajo",
        "Programar els sensors de llum, el so, els llums i els botons|Programar los sensores de luz, el sonido, las luces y los botones",
        "Controlar el robot amb variables i decisions intel·ligents|Controlar el robot con variables y decisiones inteligentes",
        "Resoldre missions: rescat, sumo, aspirador i curses|Resolver misiones: rescate, sumo, aspirador y carreras",
        "Dissenyar, programar, provar i presentar una missió pròpia|Diseñar, programar, probar y presentar una misión propia"] },
      { k: 'story', ph: 'tanca', who: 'bit', mood: 'win', t: "BIP BIP BIP! Enhorabona, enginyer/a! Has acabat el curs de robòtica. Ara ja saps el secret de tots els robots: <b>sentir, pensar i actuar</b>, provant i millorant una vegada i una altra. Fins aviat al taller!|¡BIP BIP BIP! ¡Enhorabuena, ingeniero/a! Has terminado el curso de robótica. Ahora ya sabes el secreto de todos los robots: <b>sentir, pensar y actuar</b>, probando y mejorando una y otra vez. ¡Hasta pronto en el taller!" },
      { k: 'quiz', ph: 'tanca', q: "Ara ja ho saps: què fa un enginyer/a quan el robot falla?|Ahora ya lo sabes: ¿qué hace un ingeniero/a cuando el robot falla?",
        opts: ["Mira on falla, en busca la causa, ho canvia i ho torna a provar|Mira dónde falla, busca la causa, lo cambia y vuelve a probar", "Es rendeix|Se rinde", "Diu que el robot està espatllat|Dice que el robot está estropeado"], a: 0,
        ex: "Equivocar-se forma part de construir robots, i ho has fet molt bé durant tot el curs. Enhorabona!|Equivocarse forma parte de construir robots, y lo has hecho muy bien durante todo el curso. ¡Enhorabuena!" },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
